import { createHash } from "node:crypto";
import { ARM_A_CONFIG, ArmConfigError, armAConfigHash } from "./arm-a-bare-pi.js";
import { ARM_B_CONFIG, armBConfigHash } from "./arm-b-v2-fixed.js";
import { ARM_C_CONFIG, armCConfigHash } from "./arm-c-k3-on-prime.js";

function sha256hex(text: string): string {
	return createHash("sha256").update(text, "utf8").digest("hex");
}

export const SMOKE_ONLY_NOTICE =
	"Numbers produced by this task are smoke data. The full experiment belongs to the run-evidence phase; " +
	"no figure from here may be cited as evidence of an arm-C advantage.";

// ---------------------------------------------------------------------------
// Arms, repetitions, comparisons (搂3.1鈥撀?.2)
