	Object.freeze(["C", "A"] as const),
	Object.freeze(["C", "B"] as const),
]);

/** Secondary (exploratory family, FDR-corrected). */
export const SECONDARY_COMPARISONS: readonly (readonly [ArmId, ArmId])[] = Object.freeze([
	Object.freeze(["A", "B"] as const),
