// --- operational computations (each observable is COMPUTABLE, not prose) ---

export interface TraceSpan {
	readonly turn: number;
	readonly kind: "main" | "subagent" | "tool";
	readonly tokens: number;
	/** For tool spans: the tool family used. */
	readonly tool?: "grep" | "regex" | "direct_read" | "subagent_dispatch" | "other";
}

/** obs1: turn 鈫?main-context token curve (monotone turn order, one point per turn). */
export function contextLengthCurve(spans: readonly TraceSpan[]): readonly { turn: number; tokens: number }[] {
	const byTurn = new Map<number, number>();
	for (const s of spans) if (s.kind === "main") byTurn.set(s.turn, (byTurn.get(s.turn) ?? 0) + s.tokens);
	return [...byTurn.entries()].sort((a, b) => a[0] - b[0]).map(([turn, tokens]) => ({ turn, tokens }));
}

/** obs2: subagent tokens / total tokens. */
export function subcallTokenShare(spans: readonly TraceSpan[]): number {
	let sub = 0;
	let total = 0;
	for (const s of spans) {
		total += s.tokens;
		if (s.kind === "subagent") sub += s.tokens;
	}
	if (total === 0) throw new ArmConfigError("empty trace: sub-call share undefined");
	return sub / total;
}

/** obs3: grep-tier reads / (grep-tier reads + subagent dispatches). */
export function regexSubstitutionRate(spans: readonly TraceSpan[]): number {
	let grepTier = 0;
	let dispatches = 0;
	for (const s of spans) {
		if (s.kind !== "tool") continue;
		if (s.tool === "grep" || s.tool === "regex" || s.tool === "direct_read") grepTier += 1;
		if (s.tool === "subagent_dispatch") dispatches += 1;
	}
	const denom = grepTier + dispatches;
	if (denom === 0) throw new ArmConfigError("no retrieval-or-dispatch events: substitution rate undefined");
	return grepTier / denom;
}

export interface AnswerEvent {
	readonly variable: string;
	readonly action: "set" | "overwrite";
}

/** obs4: overwrites per pre-declared answer variable. */
export function answerRevisionCounts(events: readonly AnswerEvent[]): Readonly<Record<string, number>> {
	const counts: Record<string, number> = {};
	for (const e of events) {
		if (e.action === "overwrite") counts[e.variable] = (counts[e.variable] ?? 0) + 1;
		else counts[e.variable] = counts[e.variable] ?? 0;
	}
	return Object.freeze(counts);
}

export interface HiddenLinkPoint {
	readonly cumulative_cost: number;
	readonly link_valid: boolean;
}

/** obs5: cost-sorted cumulative valid-hidden-link curve (per-arm Pareto curve raw material). */
export function hiddenLinkCurve(
	points: readonly HiddenLinkPoint[],
): readonly { cost: number; cumulative_links: number }[] {
	const sorted = [...points].sort((a, b) => a.cumulative_cost - b.cumulative_cost);
	let links = 0;
	return sorted.map((p) => {
		if (p.link_valid) links += 1;
		return { cost: p.cumulative_cost, cumulative_links: links };
	});
}

// ---------------------------------------------------------------------------
// Statistical methods (搂3.2): effect size + CI, Holm (confirmatory), FDR (exploratory)
// ---------------------------------------------------------------------------

export class StatsError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "StatsError";
	}
}

/** Cohen's d for paired/independent means (pooled SD; 0.2/0.5/0.8 are fallback anchors only). */
export function cohensD(a: readonly number[], b: readonly number[]): number {
	if (a.length < 2 || b.length < 2) throw new StatsError("need 鈮? samples per group");
	const mean = (xs: readonly number[]) => xs.reduce((s, x) => s + x, 0) / xs.length;
	const ma = mean(a);
	const mb = mean(b);
	const va = a.reduce((s, x) => s + (x - ma) ** 2, 0) / (a.length - 1);
	const vb = b.reduce((s, x) => s + (x - mb) ** 2, 0) / (b.length - 1);
	const pooled = Math.sqrt(((a.length - 1) * va + (b.length - 1) * vb) / (a.length + b.length - 2));
	if (pooled === 0) return 0;
	return (ma - mb) / pooled;
}

/** Deterministic PRNG (mulberry32) 鈥?bootstrap is reproducible under a registered seed. */
export function mulberry32(seed: number): () => number {
	let t = seed >>> 0;
	return () => {
		t = (t + 0x6d2b79f5) >>> 0;
		let x = t;
		x = Math.imul(x ^ (x >>> 15), x | 1);
		x ^= x + Math.imul(x ^ (x >>> 7), x | 61);
		return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
	};
}

/** Percentile bootstrap CI over a statistic; deterministic under seed. */
export function bootstrapCI(
	values: readonly number[],
	statistic: (xs: readonly number[]) => number,
	options: { iterations?: number; seed: number; level?: number },
): { lo: number; hi: number; point: number } {
	if (values.length < 2) throw new StatsError("need 鈮? values to bootstrap");
	const iters = options.iterations ?? 2000;
	const level = options.level ?? 0.95;
	const rng = mulberry32(options.seed);
	const stats: number[] = [];
	for (let i = 0; i < iters; i += 1) {
		const sample = Array.from({ length: values.length }, () => values[Math.floor(rng() * values.length)]);
		stats.push(statistic(sample));
	}
	stats.sort((x, y) => x - y);
	const alpha = (1 - level) / 2;
	const loIdx = Math.max(0, Math.floor(alpha * iters));
	const hiIdx = Math.min(iters - 1, Math.ceil((1 - alpha) * iters) - 1);
	return { lo: stats[loIdx], hi: stats[hiIdx], point: statistic(values) };
}

export interface CorrectionResult {
	readonly index: number;
	readonly p: number;
	readonly adjusted: number;
	readonly reject: boolean;
}

/** Holm step-down (sequential Bonferroni) 鈥?confirmatory primary comparisons (搂3.2). */
export function holmCorrection(pvals: readonly number[], alpha = 0.05): readonly CorrectionResult[] {
	if (pvals.length === 0) throw new StatsError("no p-values");
	for (const p of pvals) if (!(p >= 0 && p <= 1)) throw new StatsError(`invalid p-value ${p}`);
	const n = pvals.length;
	const order = pvals.map((p, index) => ({ p, index })).sort((a, b) => a.p - b.p);
	const results: CorrectionResult[] = new Array(n);
	let stopped = false;
	let prevAdj = 0;
	for (let k = 0; k < n; k += 1) {
		const { p, index } = order[k];
		const adj = Math.min(1, Math.max(prevAdj, (n - k) * p));
		prevAdj = adj;
		const reject = !stopped && p <= alpha / (n - k);
		if (!reject) stopped = true;
		results[index] = { index, p, adjusted: adj, reject };
	}
	return Object.freeze(results);
}

/** Benjamini鈥揌ochberg FDR 鈥?exploratory observable family (5 observables 脳 comparisons). */
export function benjaminiHochberg(pvals: readonly number[], q = 0.05): readonly CorrectionResult[] {
	if (pvals.length === 0) throw new StatsError("no p-values");
	for (const p of pvals) if (!(p >= 0 && p <= 1)) throw new StatsError(`invalid p-value ${p}`);
	const n = pvals.length;
	const order = pvals.map((p, index) => ({ p, index })).sort((a, b) => a.p - b.p);
	let maxK = -1;
	for (let k = n - 1; k >= 0; k -= 1) {
		if (order[k].p <= ((k + 1) / n) * q) {
			maxK = k;
			break;
		}
	}
	const results: CorrectionResult[] = new Array(n);
	let minAdj = 1;
	for (let k = n - 1; k >= 0; k -= 1) {
		const { p, index } = order[k];
		minAdj = Math.min(minAdj, (p * n) / (k + 1));
		results[index] = { index, p, adjusted: minAdj, reject: k <= maxK };
	}
	return Object.freeze(results);
}

/** 蠂虏 critical values at 伪=0.05 (df 1..6) for the Friedman global test (3 arms 鈬?df=2). */
const CHI2_CRIT_05: Readonly<Record<number, number>> = Object.freeze({
	1: 3.841,
	2: 5.991,
	3: 7.815,
	4: 9.488,
	5: 11.07,
	6: 12.592,
});

/**
 * Friedman test over a tasks脳arms matrix (within-task ranking; global difference BEFORE any
 * pairwise comparison, 搂3.2 妫€楠屾搴?. Returns the statistic and the 伪=0.05 verdict.
 */
export function friedmanTest(matrix: readonly (readonly number[])[]): {
	statistic: number;
	df: number;
	significant: boolean;
} {
	const nTasks = matrix.length;
	if (nTasks < 2) throw new StatsError("need 鈮? tasks (blocks)");
	const k = matrix[0].length;
	if (k < 2) throw new StatsError("need 鈮? arms");
	for (const row of matrix) if (row.length !== k) throw new StatsError("ragged matrix");
	const rankSums = new Array<number>(k).fill(0);
	for (const row of matrix) {
		const sorted = row.map((v, i) => ({ v, i })).sort((a, b) => a.v - b.v);
		const ranks = new Array<number>(k).fill(0);
		let pos = 0;
		while (pos < k) {
			let end = pos;
			while (end + 1 < k && sorted[end + 1].v === sorted[pos].v) end += 1;
			const avgRank = (pos + end + 2) / 2; // ranks are 1-based
			for (let j = pos; j <= end; j += 1) ranks[sorted[j].i] = avgRank;
			pos = end + 1;
		}
		for (let j = 0; j < k; j += 1) rankSums[j] += ranks[j];
	}
	const statistic = (12 / (nTasks * k * (k + 1))) * rankSums.reduce((s, r) => s + r * r, 0) - 3 * nTasks * (k + 1);
	const df = k - 1;
	const crit = CHI2_CRIT_05[df];
	if (crit === undefined) throw new StatsError(`no critical value for df=${df}`);
	return { statistic, df, significant: statistic > crit };
}

