/** Abort criteria (搂3.5, static, never rewritten by the system under test at run time). */
export const ABORT_CRITERIA = Object.freeze({
	canary_detection_below_floor: "freeze THAT arm and audit",
	sandbox_oom_twice: "downgrade concurrency to pure serial",
