export interface ScheduleTriple {
	readonly arm: ArmId;
	readonly task: string;
	readonly rep: number;
	readonly block: number;
	readonly exclusive_window: boolean;
}

const ARM_ROTATIONS: readonly (readonly ArmId[])[] = Object.freeze([
	Object.freeze(["A", "B", "C"] as const),
	Object.freeze(["C", "A", "B"] as const),
	Object.freeze(["B", "C", "A"] as const),
]);

/**
 * Build the FULLY SERIAL dispatch order: task blocks rotate the arm order (S4); inside a block
 * each arm runs all its reps serially (S1) before the next arm starts (S2 default). Heavy tasks
 * are flagged for an exclusive window (S3). Refuses reps below the 鈮?0 floor.
 */
export function planSchedule(
	tasks: readonly string[],
	reps: number,
	options?: { heavyTasks?: readonly string[]; smoke?: boolean },
): readonly ScheduleTriple[] {
	if (tasks.length === 0) throw new ArmConfigError("no tasks");
	if (!options?.smoke && reps < MIN_REPS_PER_TASK)
		throw new ArmConfigError(
			`reps ${reps} below the 鈮?{MIN_REPS_PER_TASK} floor (搂3.2); use smoke:true for dry runs`,
		);
	if (options?.smoke && reps < 1) throw new ArmConfigError("smoke needs 鈮? rep");
	const heavy = new Set(options?.heavyTasks ?? []);
	const out: ScheduleTriple[] = [];
	tasks.forEach((task, blockIdx) => {
		const rotation = ARM_ROTATIONS[blockIdx % ARM_ROTATIONS.length];
		for (const arm of rotation) {
			for (let rep = 1; rep <= reps; rep += 1) {
				out.push({ arm, task, rep, block: blockIdx + 1, exclusive_window: heavy.has(task) });
			}
		}
	});
	return Object.freeze(out);
}

/** One JSONL checkpoint row per finished triple (S5; G12 deterministic write). */
export function checkpointRow(
	triple: ScheduleTriple,
	result: { outcome: string; tokens: number; wall_ms: number },
): string {
	return JSON.stringify({
		arm: triple.arm,
		task: triple.task,
		rep: triple.rep,
		block: triple.block,
		outcome: result.outcome,
		tokens: result.tokens,
		wall_ms: result.wall_ms,
	});
}

/** Budget pre-calculation (搂3.4): upper bound = costliest arm unit 脳 tasks 脳 reps 脳 3 arms. */
export function budgetPrecalc(input: { costliestArmUnitUsd: number; taskCount: number; reps: number }): {
	upper_bound_usd: number;
	formula: string;
} {
	if (input.costliestArmUnitUsd <= 0 || input.taskCount <= 0) throw new ArmConfigError("invalid budget inputs");
	if (input.reps < MIN_REPS_PER_TASK)
		throw new ArmConfigError(`budget must be computed at 鈮?{MIN_REPS_PER_TASK} reps`);
	const upper = input.costliestArmUnitUsd * input.taskCount * input.reps * ARMS.length;
	return {
		upper_bound_usd: upper,
		formula: "costliest_arm_unit 脳 task_count 脳 reps(鈮?0) 脳 3 arms 鈥?computed and registered BEFORE any run",
	};
}

