export function assertRunbookPreconditions(status: readonly boolean[]): void {
	if (status.length !== RUNBOOK_PRECONDITIONS.length)
		throw new ArmConfigError(`expected ${RUNBOOK_PRECONDITIONS.length} precondition flags`);
	status.forEach((ok, i) => {
		if (!ok) throw new ArmConfigError(`runbook precondition unmet: ${RUNBOOK_PRECONDITIONS[i]}`);
	});
}

export interface ArmsRegistry {
