/** Build the experiment registry: all three arm hashes + the frozen plan, self-hashed. */
export function buildArmsRegistry(): ArmsRegistry {
	const body = {
		arm_hashes: {
			A: armAConfigHash(ARM_A_CONFIG),
			B: armBConfigHash(ARM_B_CONFIG),
			C: armCConfigHash(ARM_C_CONFIG),
		},
		min_reps: MIN_REPS_PER_TASK,
		observables: OBSERVABLES.map((o) => o.id),
		stats_plan_sha256: sha256hex(JSON.stringify(STATS_PLAN)),
		scheduling_rules: SCHEDULING_RULES.map((r) => r.id),
	};
	return Object.freeze({ ...body, registry_sha256: sha256hex(JSON.stringify(body)) });
}

/** Verify a registry snapshot: recompute everything from code; any drift is named. */
export function verifyArmsRegistry(registry: ArmsRegistry): { ok: boolean; drift: readonly string[] } {
	const fresh = buildArmsRegistry();
	const drift: string[] = [];
	for (const arm of ARMS) {
		if (registry.arm_hashes[arm] !== fresh.arm_hashes[arm]) drift.push(`arm ${arm} config hash drifted`);
	}
	if (registry.min_reps !== fresh.min_reps) drift.push("min_reps drifted");
	if (registry.stats_plan_sha256 !== fresh.stats_plan_sha256) drift.push("stats plan drifted");
	if (JSON.stringify(registry.observables) !== JSON.stringify(fresh.observables)) drift.push("observables drifted");
	if (registry.registry_sha256 !== fresh.registry_sha256) drift.push("registry self-hash drifted");
	return { ok: drift.length === 0, drift: Object.freeze(drift) };
}

/**
 * K3 implant 路 W3-T3 路 stage gate core (搂4.2: five-tuple registry, four-valued verdicts,
 * L1 deterministic short-circuit, conjunction criteria, ledger-audited advancement).
 *
 * COMPONENT TRIPLE
 * - Reason to exist : Axiom 9 architected 鈥?"push" becomes LEDGER AUDIT GATEKEEPING: a phase
 *                     advances only when the ledger PROVES the work happened. The mechanical
 *                     layer (this file + predicates.ts) is a no-LLM deterministic program; the
 *                     judgment layer (review.ts) is a context-free review subagent. If L1 can
 *                     decide, L2 is never consulted 鈥?the expensive layer only sees what the
 *                     cheap layer cannot decide (搂4.2.3).
 * - Axiom binding   : Axiom 9 (push architected); Axiom 1/2 via 搂4.2.8 (mechanical predicates
 *                     check actions, not reasoning); Axiom 5 (every verdict is a fsynced ledger
 *                     row 鈥?gate.* is in FSYNC_PREFIXES); Axiom 6 (denominator floors: small-n
 *                     ratios are unevaluable, 鈫?HOLD).
 * - Deprecation     : four-valued verdicts fold HOLD鈫扚AIL under unattended runs, but the fold
 *                     itself is ledgered (payload.folded_from, 搂4.2.2). The L1 short-circuit is
 *                     deprecable only if total per-eval cost drops below gate-management
 *                     overhead (搂4.2.10). The denominator floor is NOT deprecable (statistical
 *                     bottom line). Registry entries retire per 搂4.2.9 (100% pass rate for N
 *                     rounds with untouched criteria 鈫?advisory 鈫?retired).
 *
 * DECLARATION SURFACE = ENFORCEMENT SURFACE: the registry is a static literal in this file 鈥? * no settings read, no env read, no agent-writable config. W1 already lists `k3/gates` in
 * PROTECTED_DENY_WRITE; `installK3StageGate` (index.ts) asserts that seam at install time.
 */

