/** Registration-time L1 assertion: single-metric gates are refused (搂4.2.5 anti-Goodhart). */
export function assertRegistryWellFormed(registry: readonly GateSpec[] = GATE_REGISTRY): void {
	const seen = new Set<string>();
	for (const gate of registry) {
		if (gate.metric_set.length < 2) {
			throw new GateRegistryError(
				`gate ${gate.gate_id} declares ${gate.metric_set.length} metric(s); single-metric gates are refused (anti-Goodhart, 搂4.2.5)`,
			);
		}
		if (seen.has(gate.gate_id)) throw new GateRegistryError(`duplicate gate_id ${gate.gate_id}`);
		seen.add(gate.gate_id);
		for (const t of gate.threshold_set) {
			if (t.critical && t.provisional) {
				throw new GateRegistryError(
					`gate ${gate.gate_id} marks ${t.metric} both critical and provisional; ` +
						`uncalibrated thresholds must stay advisory and can never produce FAIL-KILL (risk R4)`,
				);
			}
		}
	}
}
assertRegistryWellFormed();

// ---------------------------------------------------------------------------
// L1 evaluation with deterministic short-circuit (搂4.2.3 / 搂4.2.4)
// ---------------------------------------------------------------------------

export interface L1Evaluation {
	readonly verdict: GateVerdict;
	/** True when a violated L1 predicate decided the verdict without consulting L2. */
	readonly short_circuit: boolean;
	readonly results: readonly PredicateResult[];
	readonly violated: readonly PredicateResult[];
	/** Violations from provisional thresholds are ADVISORY-annotated in the ledger row. */
	readonly advisory: readonly PredicateResult[];
	readonly reason_codes: readonly string[];
}

/**
 * Runs the mechanical predicate set and folds violations by severity
 * (FAIL-KILL > RECYCLE > HOLD > PASS). Hard invariant (risk R4): a provisional threshold can
 * never be the source of a FAIL-KILL 鈥?predicates declare both fields, and this function
 * throws if a predicate ever combines them (defense in depth with assertRegistryWellFormed).
 */
export function evaluateL1(ctx: L1Context, predicates: readonly L1Predicate[] = ALL_L1_PREDICATES): L1Evaluation {
	const results = predicates.map((p) => p(ctx));
	const violated = results.filter((r) => !r.ok);
	const advisory = violated.filter((r) => r.provisional);
	let verdict: GateVerdict = "PASS";
	for (const r of violated) {
		if (r.provisional && r.verdict_on_fail === "FAIL-KILL") {
			throw new ProvisionalThresholdError(
				`predicate ${r.id} would FAIL-KILL from a provisional threshold (${r.detail}); ` +
					`uncalibrated thresholds are advisory only (// PROVISIONAL: 寰?GAP-058 鏍囧畾)`,
			);
		}
		if (VERDICT_SEVERITY[r.verdict_on_fail] > VERDICT_SEVERITY[verdict]) verdict = r.verdict_on_fail;
	}
	return {
		verdict,
		short_circuit: verdict !== "PASS",
		results,
		violated,
		advisory,
		reason_codes: violated.map((r) => r.reason_code),
	};
}

// ---------------------------------------------------------------------------
// Gate decisions (four values, ledgered, HOLD folding under unattended runs)
// ---------------------------------------------------------------------------

export interface GateDecision {
	readonly gate_id: string;
	readonly verdict: GateVerdict;
	readonly reason_codes: readonly string[];
	readonly l1: L1Evaluation;
	readonly l2: L2ReviewOutcome | null;
	/** Set when an unattended run folded HOLD 鈫?FAIL-KILL (搂4.2.2 conservative fold). */
	readonly folded_from: GateVerdict | null;
	/** Per-tier cost accounting (搂4.2.3): L1 is ~free; L2 zero when short-circuited. */
	readonly tier_costs: { readonly l1_ms: number; readonly l2_ms: number };
}

export interface StageGateOptions {
	/** W2 event ledger (write side for gate.decision rows). */
	readonly ledger: EventLedger;
	/** Ledger directory (read side for the mechanical predicates). */
	readonly ledgerDir: string;
	/** Optional L2 judgment layer (review.ts). Absent 鈫?HOLD when L1 passes but L2 is required. */
	readonly reviewer?: L2Reviewer;
	/** Unattended mode: HOLD folds to FAIL-KILL, fold ledgered (搂4.2.2). */
	readonly unattended?: boolean;
	readonly now?: () => number;
}

export class StageGate {
	private readonly options: StageGateOptions;
	/** Per-phase L1 SQL result cache (搂4.2.7 B: cached within a phase, invalidated on switch). */
	private cache = new Map<string, L1Evaluation>();
	private cachedPhase: string | null = null;

	constructor(options: StageGateOptions) {
		assertRegistryWellFormed();
		this.options = options;
	}

	getGate(gateId: string): GateSpec {
		const gate = GATE_REGISTRY.find((g) => g.gate_id === gateId);
		if (!gate)
			throw new GateRegistryError(`unknown gate_id ${gateId}; gates are statically registered, not configured`);
		return gate;
	}

	/** Invalidate the per-phase predicate cache (called on phase switch). */
	invalidateCache(): void {
		this.cache.clear();
		this.cachedPhase = null;
	}

	/**
	 * Cheap mechanical admission check for the tool-call boundary (搂4.2.7 B). Only family-1/2
	 * mechanical predicates; results cached per phase. No LLM is reachable from here 鈥?this is
	 * the GAP-055 clause in executable form.
	 */
	checkToolCall(ctx: L1Context, predicates?: readonly L1Predicate[]): L1Evaluation {
		if (this.cachedPhase !== ctx.phase) this.invalidateCache();
		this.cachedPhase = ctx.phase;
		const key = `${ctx.phase}:${predicates?.length ?? "all"}`;
		const hit = this.cache.get(key);
		if (hit) return hit;
		const evaluation = evaluateL1(ctx, predicates);
		this.cache.set(key, evaluation);
		return evaluation;
	}

	/**
	 * Full gate decision (phase boundary, 搂4.2.7 C): L1 first 鈥?if L1 decides, L2 is NEVER
	 * consulted (deterministic short-circuit; L2 cost is accounted as 0). Only an L1 PASS on a
	 * gate whose verifier declares an L2 stage reaches the review layer. Verdict conjunction per
	 * 搂4.2.5; the decision is written to the ledger as a fsynced `gate.decision` row.
	 */
	async decide(
		gateId: string,
		ctx: L1Context,
		reviewInput?: Parameters<L2Reviewer["review"]>[0],
		extraPredicates?: readonly L1Predicate[],
	): Promise<GateDecision> {
		const gate = this.getGate(gateId);
		const now = this.options.now ?? Date.now;

		const l1Start = now();
		const l1 = evaluateL1(ctx, extraPredicates ? [...ALL_L1_PREDICATES, ...extraPredicates] : ALL_L1_PREDICATES);
		const l1Ms = now() - l1Start;

		let l2: L2ReviewOutcome | null = null;
		let l2Ms = 0;
		let verdict: GateVerdict = l1.verdict;

		const wantsL2 = gate.verifier.includes("l2") && reviewInput !== undefined;
		if (!l1.short_circuit && wantsL2) {
			// L1 could not decide a violation; the judgment layer reviews the evidence manifest.
			if (this.options.reviewer === undefined) {
				verdict = "HOLD"; // criteria unevaluable without the declared reviewer 鈥?never a silent PASS
			} else {
				const l2Start = now();
				l2 = await this.options.reviewer.review(reviewInput);
				l2Ms = now() - l2Start;
				// The judgment layer never produces FAIL-KILL on its own (搂4.2.3 L3 discipline
				// extended to the review stage): it contributes PASS / RECYCLE / HOLD.
				verdict = l2.verdict;
			}
		}

		// 搂4.2.2 conservative fold: unattended HOLD becomes FAIL-KILL, and the fold is ledgered
		// so "killed for being unattended" stays distinguishable from "killed on criteria".
		let foldedFrom: GateVerdict | null = null;
		if (verdict === "HOLD" && this.options.unattended === true) {
			foldedFrom = "HOLD";
			verdict = "FAIL-KILL";
		}

		const reasonCodes = [...l1.reason_codes, ...(l2?.reason_codes ?? [])];
		if (verdict === "HOLD" && reasonCodes.length === 0) reasonCodes.push("HOLD_UNEVALUABLE_NO_REVIEWER");

		const decision: GateDecision = {
			gate_id: gateId,
			verdict,
			reason_codes: reasonCodes,
			l1,
			l2,
			folded_from: foldedFrom,
			tier_costs: { l1_ms: l1Ms, l2_ms: l2Ms },
		};
		this.ledgerDecision(decision, ctx.phase);
		return decision;
	}

	/**
	 * Ledgers a B-granularity (tool-call boundary) block: the wrapper calls this before it throws,
	 * so every denied tool call is a `gate.decision` row, not a silent exception (Axiom 5).
	 */
	recordToolCallBlock(gateId: string, phase: string, evaluation: L1Evaluation): void {
		this.ledgerDecision(
			{
				gate_id: gateId,
				verdict: evaluation.verdict,
				reason_codes: evaluation.reason_codes,
				l1: evaluation,
				l2: null,
				folded_from: null,
				tier_costs: { l1_ms: 0, l2_ms: 0 },
			},
			phase,
		);
	}

	/** Writes the decision as a `gate.decision` row (fsynced via FSYNC_PREFIXES "gate."). */
	private ledgerDecision(decision: GateDecision, phase: string): void {
		this.options.ledger.append({
			event_type: "gate.decision",
			actor: { role: "gatekeeper" },
			action: decision.verdict === "PASS" ? "pass" : "deny",
			phase,
			payload: {
				gate_id: decision.gate_id,
				verdict: decision.verdict,
				reason_codes: decision.reason_codes,
				l1_short_circuit: decision.l1.short_circuit,
				l1_violated: decision.l1.violated.map((r) => r.id),
				l1_advisory: decision.l1.advisory.map((r) => r.id),
				l2_consulted: decision.l2 !== null,
				folded_from: decision.folded_from,
				tier_costs: decision.tier_costs,
			},
			idem_key: null,
		});
		if (decision.verdict === "FAIL-KILL" && decision.folded_from === null) {
			const critical = decision.l1.violated.some((r) => r.verdict_on_fail === "FAIL-KILL");
			if (critical) {
				this.options.ledger.append({
					event_type: "security.escalate",
					actor: { role: "gatekeeper" },
					action: "escalate",
					phase,
					payload: { gate_id: decision.gate_id, reason_codes: decision.reason_codes },
					idem_key: null,
				});
			}
		}
	}
}

