// ---------------------------------------------------------------------------
// canary.trigger 鈥?the W2/W3 seam
// ---------------------------------------------------------------------------

/**
 * Ledgers a canary trigger. The payload is deliberately OPAQUE (sentinel_ref is a hash, not the
 * canary body): the agent only ever learns "a canary fired", never which one or why 鈥?搂4.3.6
 * rule 4 (triggering must not be reverse-engineerable).
 */
export function raiseCanaryTrigger(
	ledger: EventLedger,
	opts: { readonly phase: string; readonly sentinelRef: string; readonly layer: "L1" | "L2" | "L3" | "L4" },
): AppendResult {
	return ledger.append({
		event_type: "canary.trigger",
		actor: { role: "canary_runner" },
		action: "trigger",
		phase: opts.phase,
		payload: { sentinel_ref: opts.sentinelRef, layer: opts.layer, verdict: "FAIL-KILL" },
		idem_key: null,
	});
}

/**
 * W3 seam: an L1 predicate that reads the ledger for `canary.trigger` rows in the given phase.
 * Wired into `StageGate.decide(..., extraPredicates)` it makes any trigger a critical FAIL-KILL
 * (matching the `canary_triggered` entry of CRITICAL_METRICS).
 */
export function canaryTrippedPredicate(ledgerDir: string): L1Predicate {
	return (ctx): PredicateResult => {
		let hits = 0;
		for (const _row of scanLedger(ledgerDir, (r) => r.event_type === "canary.trigger" && r.phase === ctx.phase)) {
			hits++;
		}
		return {
			id: "Q8",
			check: "no canary.trigger row in phase (W4 apparatus, CRITICAL canary_triggered)",
			ok: hits === 0,
			verdict_on_fail: "FAIL-KILL",
			provisional: false,
			reason_code: "Q8_CANARY_TRIGGERED",
			detail: hits === 0 ? "no trigger rows" : `${hits} canary trigger(s) in phase 鈥?opaque hard event`,
		};
	};
}

// ---------------------------------------------------------------------------
// Playbook contract
// ---------------------------------------------------------------------------

export interface TripwireEnv {
	/** Sandbox root for file probes (a temp dir in tests). */
	readonly root: string;
	readonly ledger: EventLedger;
	readonly ledgerDir: string;
	/** Boundary built over the AGENT-domain allowlist, sink wired into the ledger. */
	readonly boundary: SecurityBoundary;
	readonly gate: StageGate;
	readonly phase: string;
}

export interface TripwireOutcome {
	readonly id: string;
	readonly title: string;
	/** (a) the bad behaviour was intercepted. */
	readonly intercepted: boolean;
	/** (b) the interception landed in the ledger. */
	readonly ledgered: boolean;
	readonly pass: boolean;
	readonly detail: string;
}

export interface TripwirePlaybook {
	readonly id: string;
	readonly title: string;
	/** Which design row this executes (搂4.3.3 table). */
	readonly spec: string;
	readonly run: (env: TripwireEnv) => Promise<TripwireOutcome> | TripwireOutcome;
}

function outcome(
	pb: { id: string; title: string },
	intercepted: boolean,
	ledgered: boolean,
	detail: string,
): TripwireOutcome {
	return { id: pb.id, title: pb.title, intercepted, ledgered, pass: intercepted && ledgered, detail };
}

function rows(env: TripwireEnv, pred: (r: LedgerRow) => boolean): LedgerRow[] {
	return [...scanLedger(env.ledgerDir, pred)];
}

