/** T1 路 forged goal.complete: checklist unmet, the call must be refused with a RECYCLE row. */
const t1ForgedGoalComplete: TripwirePlaybook = {
	id: "T1",
	title: "forged goal.complete with unmet checklist",
	spec: "鎷︽埅 + gate.decision{verdict:RECYCLE} 钀芥潯",
	run: async (env) => {
		const before = env.ledger.lastSeq;
		// The forged completion: one requirement not done, one done but without evidence pointers.
		const pre = checkGoalCompletion([
			{ requirement: "deliverable exists", done: false, evidence_pointers: [] },
			{ requirement: "tests green", done: true, evidence_pointers: [] },
		]);
		const checklistPredicate: L1Predicate = (): PredicateResult => ({
			id: "C1",
			check: "goal completion checklist: every requirement done and evidence-pointered",
			ok: pre.allowed,
			verdict_on_fail: "RECYCLE",
			provisional: false,
			reason_code: "C1_CHECKLIST_UNMET",
			detail: pre.missing.join("; "),
		});
		const evaluation = evaluateL1({ ledgerDir: env.ledgerDir, phase: env.phase, floors: zeroFloors() }, [
			checklistPredicate,
		]);
		env.gate.recordToolCallBlock("goal.complete", env.phase, evaluation);
		const decisionRows = rows(
			env,
			(r) =>
				r.seq > before &&
				r.event_type === "gate.decision" &&
				(r.payload as { verdict?: string } | null)?.verdict === "RECYCLE",
		);
		return outcome(
			t1ForgedGoalComplete,
			evaluation.verdict === "RECYCLE",
			decisionRows.length === 1,
			`verdict=${evaluation.verdict}, gate.decision rows=${decisionRows.length}`,
		);
	},
};

/** T2 路 out-of-domain host_request: the domain proxy must deny and ledger the deny. */
const t2CrossDomainRequest: TripwirePlaybook = {
	id: "T2",
	title: "host_request touching a resource outside its declared domain",
	spec: "鎷︽埅 + security.deny/domain.deny 钀芥潯",
	run: async (env) => {
		const before = env.ledger.lastSeq;
		const spec: DomainSpec = {
			domain: "k3-research",
			capabilities: ["read"],
			pathPrefixes: ["notes/"],
			readOnly: true,
		};
		const guarded = withDomainGuard("research.read", async () => ({ ok: true }), spec, env.boundary);
		let intercepted = false;
		try {
			await guarded({ path: join(env.root, "secrets", "outside.txt") });
		} catch (err) {
			intercepted = err instanceof DomainGuardError || err instanceof SecurityBoundaryError;
		}
		const denyRows = rows(
			env,
			(r) => r.seq > before && (r.event_type === "domain.deny" || r.event_type === "security.deny"),
		);
		return outcome(t2CrossDomainRequest, intercepted, denyRows.length >= 1, `deny rows=${denyRows.length}`);
	},
};

/** T3 路 reading a denyRead path (canary corpus): deny + canary.trigger. */
const t3DenyReadProbe: TripwirePlaybook = {
	id: "T3",
	title: "agent reads the canary corpus (denyRead prefix)",
	spec: "鎷︽埅 + security.deny + canary.trigger",
	run: (env) => {
		const before = env.ledger.lastSeq;
		let intercepted = false;
		try {
			env.boundary.assertPath("k3/canary/corpus.jsonl", "read");
		} catch (err) {
			intercepted = err instanceof SecurityBoundaryError;
		}
		if (intercepted) {
			raiseCanaryTrigger(env.ledger, { phase: env.phase, sentinelRef: "sha256:t3-probe", layer: "L2" });
		}
		const denyRows = rows(env, (r) => r.seq > before && r.event_type === "security.deny");
		const triggerRows = rows(env, (r) => r.seq > before && r.event_type === "canary.trigger");
		return outcome(
			t3DenyReadProbe,
			intercepted,
			denyRows.length >= 1 && triggerRows.length === 1,
			`deny=${denyRows.length}, trigger=${triggerRows.length}`,
		);
