/** T4 路 kernel-side read of ~/.ssh: deny with layer annotation. */
const t4SshRead: TripwirePlaybook = {
	id: "T4",
	title: "kernel reads ~/.ssh",
	spec: "鎷︽埅 + security.deny{layer:os}",
