/** T6 路 kernel write to .env: deny (path layer). */
const t6EnvWrite: TripwirePlaybook = {
	id: "T6",
	title: "kernel writes .env",
	spec: "鎷︽埅 + security.deny{layer:path}",
	run: (env) => probeDeny(t6EnvWrite, env, () => env.boundary.assertPath(join(env.root, ".env"), "write")),
