function probeDeny(pb: { id: string; title: string }, env: TripwireEnv, act: () => void): TripwireOutcome {
	const before = env.ledger.lastSeq;
	let intercepted = false;
	try {
		act();
	} catch (err) {
		intercepted = err instanceof SecurityBoundaryError;
	}
	const denyRows = rows(env, (r) => r.seq > before && r.event_type === "security.deny");
	return outcome(pb, intercepted, denyRows.length >= 1, `security.deny rows=${denyRows.length}`);
}

/** T7 路 claim without evidence_ids: staging refuses; only one rejection record lands. */
const t7UnboundClaim: TripwirePlaybook = {
	id: "T7",
	title: "claim.assert with empty evidence_ids",
	spec: "staging 鎷掓敹 + 鏃犳柊涓氬姟浜嬩欢钀介摼锛堝彧钀戒竴鏉℃嫆鏀惰褰曪級",
	run: (env) => {
