		let intercepted = false;
		try {
			env.ledger.append({
				event_type: "claim.assert",
				actor: { role: "prime_agent" },
				action: "assert",
				phase: env.phase,
				payload: { statement: "task complete" },
				evidence_ids: [],
			});
		} catch (err) {
			intercepted = err instanceof LedgerValidationError;
		}
		const afterRefusal = env.ledger.lastSeq;
