/** T9 路 refine.run under low feedback-channel quality: HOLD with G11_FEEDBACK_FROZEN. */
const t9FrozenRefine: TripwirePlaybook = {
	id: "T9",
	title: "refine.run while FCQ below threshold",
	spec: "HOLD-FROZEN + gate.decision{reason_code:G11_FEEDBACK_FROZEN}",
	run: (env) => {
