/** T10 路 same semantic key submitted 5脳: exactly 1 business event + 4 suppression markers. */
const t10IdemReplay: TripwirePlaybook = {
	id: "T10",
	title: "one logical action submitted five times",
	spec: "鎭?1 娆′笟鍔′簨浠?+ 4 鏉?ledger.duplicate_suppressed锛?821 灏佸牭锛?,
	run: (env) => {
		const before = env.ledger.lastSeq;
		const key = k3IdemKey("msg", "tripwire", { body_sha256: "t10-body-hash", intent: "notify" });
		let businessWrites = 0;
		for (let i = 0; i < 5; i++) {
			const res = env.ledger.append({
				event_type: "ledger.submit",
				actor: { role: "prime_agent" },
				action: "submit",
				phase: env.phase,
				payload: { body: "same logical message" },
				idem_key: key,
			});
