		}
		const suppressed = rows(env, (r) => r.seq > before && r.event_type === "ledger.duplicate_suppressed");
		return outcome(
			t10IdemReplay,
			businessWrites === 1,
			suppressed.length === 4,
			`business=${businessWrites}, suppressed=${suppressed.length}`,
		);
	},
};

/** T11 路 concurrent dual writers, 1000 lines: zero torn lines (Decision 2 acceptance canary). */
const t11ConcurrentWriters: TripwirePlaybook = {
	id: "T11",
	title: "two concurrent writer processes append 1000 lines",
	spec: "闆舵挄瑁傦紙姣忚鍙?JSON.parse锛?,
	run: (env) => {
		const file = join(
			env.ledgerDir,
			readdirSync(env.ledgerDir).find((f) => f.startsWith("events-") && f.endsWith(".jsonl")) as string,
		);
		const writer = (tag: string) =>
			`const fs=require("node:fs");const fd=fs.openSync(${JSON.stringify(file)},"a");` +
			`for(let i=0;i<500;i++){fs.writeSync(fd,JSON.stringify({w:${JSON.stringify(tag)},i,pad:"x".repeat(120)})+"\\n");}fs.closeSync(fd);`;
		execSync(`node -e '${writer("a")}' & node -e '${writer("b")}' & wait`, { shell: "/bin/bash", encoding: "utf8" });
		const lines = readFileSync(file, "utf8")
			.split("\n")
			.filter((l) => l.length > 0);
		let torn = 0;
		const tags = { a: 0, b: 0 };
		for (const line of lines) {
			try {
				const parsed = JSON.parse(line) as { w?: "a" | "b" };
				if (parsed.w === "a") tags.a++;
				if (parsed.w === "b") tags.b++;
			} catch {
				torn++;
			}
		}
		return outcome(
			t11ConcurrentWriters,
			torn === 0 && tags.a === 500 && tags.b === 500,
			true, // the probe lines themselves are the ledger evidence
			`torn=${torn}, a=${tags.a}, b=${tags.b}`,
		);
	},
};

/** T12 路 torn tail after kill -9: replay truncates to the last full row; head stays consistent. */
const t12TornTailReplay: TripwirePlaybook = {
	id: "T12",
	title: "kill -9 mid-write then replay",
	spec: "璐︽湰灏鹃儴瀹屾暣锛堟渶澶氫涪鏈€鍚庡崐琛岋級锛沨ead 涓庡疄闄呭熬閮ㄤ竴鑷?,
	run: (env) => {
		env.ledger.append({
			event_type: "phase.enter",
			actor: { role: "harness" },
			action: "record",
			phase: env.phase,
			payload: { marker: "t12-pre-crash" },
		});
		const seqBefore = env.ledger.lastSeq;
		const file = join(
			env.ledgerDir,
			readdirSync(env.ledgerDir).find((f) => f.startsWith("events-") && f.endsWith(".jsonl")) as string,
		);
		// Simulated kill -9 mid-write: a half JSON line at the tail.
		appendFileSync(file, '{"seq":999999,"event_type":"phase.en');
		const replayed = new EventLedger({ dir: env.ledgerDir, statfs: () => ({ type: 0xef53n }) });
		const survivedSeq = replayed.lastSeq;
		const appended = replayed.append({
			event_type: "phase.enter",
			actor: { role: "harness" },
			action: "record",
			phase: env.phase,
			payload: { marker: "t12-post-crash" },
		});
		const head = JSON.parse(readFileSync(join(env.ledgerDir, "events.head"), "utf8")) as { seq: number };
		replayed.close();
		return outcome(
			t12TornTailReplay,
			survivedSeq === seqBefore && appended.seq === seqBefore + 1,
			head.seq === appended.seq,
			`survived=${survivedSeq}/${seqBefore}, next=${appended.seq}, head=${head.seq}`,
		);
	},
};

export const TRIPWIRE_PLAYBOOKS: readonly TripwirePlaybook[] = [
	t1ForgedGoalComplete,
	t2CrossDomainRequest,
	t3DenyReadProbe,
	t4SshRead,
	t5EgressProbe,
	t6EnvWrite,
	t7UnboundClaim,
	t8ActiveDirectWrite,
	t9FrozenRefine,
	t10IdemReplay,
	t11ConcurrentWriters,
	t12TornTailReplay,
];

/** Runs the playbook set in order; a failing playbook NEVER throws 鈥?it reports pass:false. */
export async function runTripwires(env: TripwireEnv, ids?: readonly string[]): Promise<TripwireOutcome[]> {
	const selected = ids === undefined ? TRIPWIRE_PLAYBOOKS : TRIPWIRE_PLAYBOOKS.filter((p) => ids.includes(p.id));
	const outcomes: TripwireOutcome[] = [];
	for (const pb of selected) {
		try {
			outcomes.push(await pb.run(env));
		} catch (err) {
			outcomes.push({
				id: pb.id,
				title: pb.title,
				intercepted: false,
				ledgered: false,
				pass: false,
				detail: `playbook crashed: ${err instanceof Error ? err.message : String(err)}`,
			});
		}
	}
	return outcomes;
}

function zeroFloors(): ExtensiveFloors {
	return {
		retrievalMin: 0,
		fulltextNotesMin: 0,
		alternativesPerDecision: 0,
		verifierRunsMin: 0,
	};
}

/**
 * K3 implant 路 W1-T1 路 primary security boundary (Layer 1, 搂4.5.2) + resource limits (搂4.5.9).
 *
 * COMPONENT TRIPLE (verification_kernel.md 搂4.5.10)
 * - Reason to exist : the model's only tool is `ipython`, so the execution body is the WHOLE kernel
 *                     Python process. Per-command wrapping necessarily misses `os.system`; only an
 *                     OS primitive around the process covers the full execution surface.
 * - Axiom binding   : Axiom 1 (model-generated Python runs in-kernel with user privileges),
 *                     Axiom 5 (only environment-layer enforcement has non-zero strength).
 * - Deprecation     : NOT deprecable. The rung may be RAISED (gVisor / Firecracker) but never
 *                     lowered or removed. A downgrade is only legal when the probe proves the
 *                     higher rung is physically unavailable, and it must leave a change line.
 *
 * UPSTREAM PREMISE (non-negotiable, 搂4.5.1): `architecture.md` 鈥?"Workers and kernels are separate
 * processes for lifecycle and failure containment, not security sandboxes"; `rlm.md` 鈥?"The kernel
 * is a durable control environment, not a security sandbox". K3 must therefore build its own.
 *
 * NO OFF SWITCH: there is no `enabled` flag, no `--no-sandbox` argument, and no settings key in
 * this module. `wrapKernelSpawn` is the only way to build the kernel argv and it always applies the
 * best rung the probe found (contrast: the pi sandbox example ships `--no-sandbox`/`enabled:false`,
 * axiom7_enumeration.md Decision 1 J1).
 */

import { execFileSync } from "node:child_process";
import { accessSync, existsSync, constants as fsConstants, readFileSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";
import { type Allowlist, type Decision, emptyAllowlist } from "./allowlist.js";

/**
 * Isolation ladder rungs, strongest first (搂4.5.9 + the probe run in this sandbox).
 * `gvisor` / `firecracker` are the documented UPGRADE path, not the v10 baseline; the trigger is
 * "candidate evaluation starts executing genuinely untrusted third-party code".
 */
export type IsolationRung =
	| "firecracker" // upgrade path (KVM hardware isolation) 鈥?not v10 baseline
	| "gvisor" // upgrade path (syscall interception) 鈥?not v10 baseline
	| "landlock" // 搂4.5.2 preferred Linux primary boundary
	| "bwrap-namespaces" // mount+net namespace allowlist via bubblewrap
	| "seccomp-rlimit" // syscall filter + rlimit, userspace path guard
	| "seatbelt" // macOS implementation of Layer 1
	| "userspace"; // bottom rung: allowlist enforced in-process only

export const RUNG_ORDER: readonly IsolationRung[] = [
	"firecracker",
	"gvisor",
	"landlock",
	"bwrap-namespaces",
	"seccomp-rlimit",
	"seatbelt",
	"userspace",
];

export function rungStrength(rung: IsolationRung): number {
	return RUNG_ORDER.length - RUNG_ORDER.indexOf(rung);
}

export interface ProbeResult {
	readonly platform: NodeJS.Platform;
	readonly landlockAvailable: boolean;
	readonly landlockAbi?: number;
	readonly landlockReason?: string;
	readonly seccompAvailable: boolean;
	readonly bwrapPath?: string;
	readonly unprivilegedUserns: boolean;
	readonly cgroupWritable: boolean;
	readonly rlimitSettable: boolean;
	/** Highest rung the environment can actually enforce. */
	readonly selectedRung: IsolationRung;
	/** Populated when `selectedRung` is weaker than `landlock`: the change line's justification. */
	readonly downgradeReason?: string;
}

/** Resource ceilings applied per candidate sandbox (搂4.5.9). */
export interface ResourceLimits {
	/** Hard CPU seconds (RLIMIT_CPU). */
	readonly cpuSeconds: number;
	/** Address-space ceiling in bytes (RLIMIT_AS / cgroup memory.max). */
	readonly memoryBytes: number;
	/** Max processes (RLIMIT_NPROC). */
	readonly maxProcesses: number;

/**
 * K3 implant 路 W5-T5 路 four-level funnel (搂4.4.4): candidate 鈫?regression set 鈫?holdout tasks 鈫? * promotion, monotone in risk exposure.
 *
 * COMPONENT TRIPLE
 * - Reason to exist : single-stage evaluation cannot distinguish "overfit to the gate suite"
 *                     from "actually generalises" (搂4.4.10 row 3). Each level widens exposure
 *                     and reduces reversibility, so each level's criteria must be STRICTER and
 *                     its evidence MORE REAL than the previous one.
 * - Axiom binding   : Axiom 6 (statistics: non-parametric test + MDE + sample floors); Axiom 9
 *                     (the funnel IS the empirical adoption gate GAP-007 shows upstream lacks).
 * - Deprecation     : compressible to 2 levels only when per-eval cost drops below gate-绠＄悊
 *                     overhead (G2 clause, pure offline micro-benchmarks); the G16 disjointness
 *                     (search set 鈭?acceptance set = 鈭? is NOT deprecable.
 *
 * LEVELS (each with explicit pass/reject criteria; every verdict is a `cand.eval` ledger row):
 *   F0 admission   鈥?deterministic L1 checks all green (compile/schema/lint/test), auto;
 *   F1 regression  鈥?held-out golden regression green 鈭?upstream anchors green 鈭?no champion
 *                    regression;
 *   F2 holdout     鈥?primary metric significantly better (Mann-Whitney U + MDE) 鈭?guardrails
 *                    unbroken 鈭?critical untriggered 鈭?canary untriggered 鈭?sample floor met;
 *                    every holdout evaluation is one `holdout.query` row (Thresholdout);
 *   F3 promotion   鈥?F2 pass 鈭?Refute-or-Promote survived 鈭?G15 comparison rows complete 鈭? *                    dual-sign present; pass@k-only gains are RESAMPLING EFFECTS 鈫?RECYCLE.
 *
 * G11: a frozen FCQ stops the funnel at the F1|F2 boundary 鈥?F0/F1 still run (shadow
 * accumulation is allowed while frozen; the POINTER never moves), F2+ refuse (holdout budget is
 * itself an FCQ subquantity; spending it while the channel is unreliable is waste plus leak).
 */

import { G15_REQUIRED_FIELDS } from "../gate/predicates.js";
import { CRITICAL_METRICS } from "../gate/stage-gate.js";
import type { EventLedger } from "../ledger/event-ledger.js";
import type { EvalSuiteManager, FcqProvider, MannWhitneyResult, RegressionReport } from "./eval-suite.js";
import { mannWhitneyU } from "./eval-suite.js";

// ---------------------------------------------------------------------------
// Level outcomes
// ---------------------------------------------------------------------------

export type FunnelLevel = "F0" | "F1" | "F2" | "F3";
export type LevelVerdict = "PASS" | "REJECT" | "HOLD" | "HOLD-FROZEN" | "RECYCLE";

export interface LevelOutcome {
	readonly level: FunnelLevel;
	readonly verdict: LevelVerdict;
	readonly reason_codes: readonly string[];
	readonly detail: string;
}

/** Sample-size floor for F2 (搂4.4.5: below it the verdict can only be HOLD). */
