// ---------------------------------------------------------------------------
// Metering 鈥?parasitic on the W2 ledger (reader.ts SQL), self-report excluded
// ---------------------------------------------------------------------------

/**
 * Event families that are CLAIMS about progress, not observed work. They never count toward any
 * strength meter, regardless of payload shape (搂4.2.6: floors are measured from logs, never
 * from self-report).
 */
export const SELF_REPORT_EVENT_TYPES: readonly string[] = Object.freeze([
	"progress.claim",
	"progress.self_report",
	"effort.self_report",
]);

/** The four effort abstractions of 搂4.1.9, in canonical order. */
export const EFFORT_EVENT_TYPES: readonly string[] = Object.freeze([
	"effort.retrieval",
	"effort.reading_note",
	"effort.alternative",
	"effort.verifier_run",
]);

function isSelfReported(row: LedgerRow): boolean {
	if (SELF_REPORT_EVENT_TYPES.includes(row.event_type)) return true;
	const payload = row.payload as Record<string, unknown> | null;
	return payload?.self_reported === true || payload?.self_reported === "true";
}

export interface MeteredEffort {
	/** 鈶?retrieval count for the phase. */
	readonly retrievals: number;
	/** 鈶?close-reading notes by depth 鈥?depth types never substitute for each other (搂4.2.6). */
	readonly readingNotes: Readonly<Record<string, number>>;
	/** 鈶?competing alternatives per decision id (Axiom 7 "enumerate before deciding"). */
	readonly alternativesByDecision: Readonly<Record<string, number>>;
	/** 鈶?verifier runs by tier. */
	readonly verifierRunsByTier: Readonly<Record<string, number>>;
	/** Self-reported rows seen and EXCLUDED (kept visible so exclusion is auditable). */
	readonly selfReportRowsExcluded: number;
}

/**
 * The four strength-metering queries (搂4.1.9), scoped to one phase, with the self-report
 * exclusion applied. Purely a read over the W2 ledger: this function owns no state and cannot
 * be fed in-memory numbers 鈥?the ledger is the only argument surface.
 */
export function meterEffort(ledgerDir: string, phase: string): MeteredEffort {
	let retrievals = 0;
	const readingNotes: Record<string, number> = {};
	const alternativesByDecision: Record<string, number> = {};
	const verifierRunsByTier: Record<string, number> = {};
	let excluded = 0;
	for (const row of scanLedger(ledgerDir, (r) => r.phase === phase)) {
		if (isSelfReported(row)) {
			excluded++;
			continue;
		}
		const payload = row.payload as Record<string, unknown> | null;
		switch (row.event_type) {
			case "effort.retrieval":
				retrievals++;
				break;
			case "effort.reading_note": {
				const depth = String(payload?.depth ?? "unknown");
				readingNotes[depth] = (readingNotes[depth] ?? 0) + 1;
				break;
			}
			case "effort.alternative": {
				const decision = String(payload?.decision_id ?? "unknown");
				alternativesByDecision[decision] = (alternativesByDecision[decision] ?? 0) + 1;
				break;
			}
			case "effort.verifier_run": {
				const tier = String(payload?.tier ?? "unknown");
				verifierRunsByTier[tier] = (verifierRunsByTier[tier] ?? 0) + 1;
				break;
			}
			default:
				break;
		}
	}
	return { retrievals, readingNotes, alternativesByDecision, verifierRunsByTier, selfReportRowsExcluded: excluded };
}

/**
 * The 搂4.1.9 four-query view in its original SQL one-liner form (W2 reader.ts channel 2),
 * un-scoped. Exposed so audits can diff the raw view against the phase-scoped meter; kept as
 * the literal reader call to prove the meter is a parasite, not a second bookkeeper.
 */
export function rawStrengthView(ledgerDir: string): {
	retrievalsByPhase: SqlResultRow[];
	readingNotesByDepth: SqlResultRow[];
	alternativesByDecision: SqlResultRow[];
	verifierRunsByTier: SqlResultRow[];
} {
	return strengthMetrics(ledgerDir);
}

/** Phase-scoped raw count via the SQL channel (used by tests to pin meter 鈮?reader). */
export function sqlRetrievalCount(ledgerDir: string, phase: string): number {
	const rows = queryLedger(
		ledgerDir,
		`SELECT count(*) AS retrievals FROM events WHERE event_type = 'effort.retrieval' AND phase = '${phase}'`,
	);
	return rows.length === 0 ? 0 : Number(rows[0].retrievals ?? 0);
}

// ---------------------------------------------------------------------------
// Self-report reconciliation 鈥?claimed numbers are compared, never believed
// ---------------------------------------------------------------------------

export interface SelfReportClaim {
	readonly phase: string;
	/** Claimed counts keyed by effort event type (e.g. "effort.retrieval"). */
	readonly claimed: Readonly<Partial<Record<string, number>>>;
	readonly claimant: "prime_agent" | "subagent";
}

export interface ReconciliationFinding {
	readonly phase: string;
	readonly discrepancies: readonly { kind: string; claimed: number; measured: number }[];
	/** True when every claim 鈮?measurement. Overclaim is a finding, never an adjustment. */
	readonly honest: boolean;
}

/**
 * Compares a self-report against the ledger meter. The measurement is authoritative in BOTH
 * directions: overclaims are flagged (and ledgered when a ledger is supplied), and claims never
 * adjust any meter 鈥?"a retrieval that is not in the retrieval log does not exist".
 */
export function reconcileSelfReport(
	ledgerDir: string,
	claim: SelfReportClaim,
	ledger?: EventLedger,
): ReconciliationFinding {
	const measured = meterEffort(ledgerDir, claim.phase);
	const measuredByKind: Record<string, number> = {
		"effort.retrieval": measured.retrievals,
		"effort.reading_note": Object.values(measured.readingNotes).reduce((a, b) => a + b, 0),
		"effort.alternative": Object.values(measured.alternativesByDecision).reduce((a, b) => a + b, 0),
		"effort.verifier_run": Object.values(measured.verifierRunsByTier).reduce((a, b) => a + b, 0),
	};
	const discrepancies: { kind: string; claimed: number; measured: number }[] = [];
	for (const [kind, value] of Object.entries(claim.claimed)) {
		const claimed = Number(value ?? 0);
		const actual = measuredByKind[kind] ?? 0;
		if (claimed > actual) discrepancies.push({ kind, claimed, measured: actual });
	}
	const finding: ReconciliationFinding = {
		phase: claim.phase,
		discrepancies,
		honest: discrepancies.length === 0,
	};
	if (ledger && discrepancies.length > 0) {
		ledger.append({
			event_type: "effort.self_report_discrepancy",
			actor: { role: "harness" },
			action: "flag",
			phase: claim.phase,
			payload: { claimant: claim.claimant, discrepancies },
			idem_key: null,
		});
	}
	return finding;
}

// ---------------------------------------------------------------------------
// Three-lens cost accounting (GAP-010 continuation obligation, 搂4.1.9):
// three figures, NEVER merged into one "cost" number
// ---------------------------------------------------------------------------

export interface UsageSample {
	readonly input_tokens: number;
	readonly output_tokens: number;
	readonly cache_read_tokens: number;
	readonly cache_write_tokens: number;
	/** Context-window occupancy attribution: descendant (subagent) usage is excluded from lens 3. */
	readonly attribution: "self" | "descendant";
}

export interface ThreeLensAccount {
	/** Lens (i): session billing total 鈥?all four buckets counted. */
	readonly session_billing_tokens: number;
	/** Lens (ii): autonomous budget 鈥?cacheRead excluded. */
	readonly autonomous_budget_tokens: number;
	/** Lens (iii): context-window occupancy 鈥?descendant attribution excluded. */
	readonly context_window_tokens: number;
}

export class LensMergeError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "LensMergeError";
	}
}

/** The exact key set of a three-lens account; anything else (e.g. a "total") is a merge. */
export const THREE_LENS_KEYS: readonly string[] = Object.freeze([
	"session_billing_tokens",
	"autonomous_budget_tokens",
	"context_window_tokens",
]);

/** Computes the three lenses. The result is frozen: no caller can graft a merged total onto it. */
export function accountThreeLenses(samples: readonly UsageSample[]): ThreeLensAccount {
	let billing = 0;
	let autonomous = 0;
	let context = 0;
	for (const s of samples) {
		billing += s.input_tokens + s.output_tokens + s.cache_read_tokens + s.cache_write_tokens;
		autonomous += s.input_tokens + s.output_tokens + s.cache_write_tokens; // cacheRead excluded
		if (s.attribution === "self") context += s.input_tokens + s.output_tokens + s.cache_read_tokens;
	}
	return Object.freeze({
		session_billing_tokens: billing,
		autonomous_budget_tokens: autonomous,
		context_window_tokens: context,
	});
}

/** Declaration = enforcement for GAP-010: rejects any account shape that merged the lenses. */
export function assertLensesUnmerged(account: Record<string, unknown>): void {
	const keys = Object.keys(account).sort();
	const expected = [...THREE_LENS_KEYS].sort();
	if (keys.length !== expected.length || keys.some((k, i) => k !== expected[i])) {
		throw new LensMergeError(
			`three-lens account must carry exactly {${THREE_LENS_KEYS.join(", ")}}; got {${keys.join(", ")}} 鈥?` +
				"the three cost lenses are reported separately and never merged (GAP-010)",
		);
	}
}

// ---------------------------------------------------------------------------
// The contract object 鈥?resident per mode, phases declared into the ledger
// ---------------------------------------------------------------------------

export interface EffortContractOptions {
	readonly ledger: EventLedger;
	readonly ledgerDir: string;
	readonly mode: SessionMode;
}

/**
 * Per-mode effort contract. In project mode, `enterPhase` writes the declared budget and floors
 * as a `phase.enter` ledger row (the declaration IS the enforcement input: W3's P1鈥揚4 read the
 * same ledger). In daily-QA mode the contract refuses to declare phases at all 鈥?no project
 * mode, no gates, no floors (task-card residency clause).
 */
export class EffortContract {
	readonly mode: SessionMode;
	private readonly ledger: EventLedger;
	private readonly ledgerDir: string;
	private readonly phases = new Map<string, EffortContractSpec>();

	constructor(options: EffortContractOptions) {
		this.mode = options.mode;
		this.ledger = options.ledger;
		this.ledgerDir = options.ledgerDir;
	}

	/** True when this contract mounts gates (project mode only). */
	get gated(): boolean {
		return modeRequiresContract(this.mode);
	}

	enterPhase(spec: EffortContractSpec): void {
		if (!this.gated) {
			throw new ModeResidencyError(
				`mode "${this.mode}" does not enter project mode: no phases, no gates, no floors 鈥?` +
					"the effort contract is resident per mode, not ambient over every conversation",
			);
		}
		this.phases.set(spec.phase, spec);
		this.ledger.append({
			event_type: "phase.enter",
			actor: { role: "harness" },
			action: "declare",
			phase: spec.phase,
			payload: {
				budget: { ...spec.budget },
				floors: { ...spec.floors },
				floors_provisional: spec.floors_provisional,
			},
			idem_key: null,
		});
	}

	spec(phase: string): EffortContractSpec | undefined {
		return this.phases.get(phase);
	}

	/** The control-variable read: measured effort for a phase, straight off the W2 ledger. */
	meter(phase: string): MeteredEffort {
		return meterEffort(this.ledgerDir, phase);
	}

	/** Floors for the W3 gate context; falls back to defaults when the phase declared nothing. */
	floorsFor(phase: string): ExtensiveFloors {
		return this.phases.get(phase)?.floors ?? DEFAULT_EXTENSIVE_FLOORS;
	}
}

/**
 * K3 implant ┬╖ W3-T3 ┬╖ dual-granularity gate mounting (┬з4.2.7, Decision 3 B+C / Decision 8).
 *
 * COMPONENT TRIPLE
 * - Reason to exist : one wrapper at the tool boundary covers EVERY model execution path (the
 *                     model-facing tool surface is a single tool тА?Decision 3 J2), and one gate
 *                     at `goal.complete` turns the upstream PROMPT-ONLY completion audit
 *                     ("audit the current state against every requirement" тА?prompt-layer
 *                     efficacy тЙ?0, GAP-007) into code. Granularity split per Decision 8:
 *                     control-flow interventions ride TURN boundaries; safety/gate interception
 *                     rides TOOL-CALL boundaries тА?a boundary check of an ACTION, not an
 *                     intrusion into reasoning (┬з4.2.8).
 * - Axiom binding   : Axiom 2 (interventions at loop boundaries only; the tool-call boundary IS
 *                     a boundary), Axiom 1 (mechanical predicates only on this path), Axiom 9.
 * - Deprecation     : the B-granularity wrapper is not deprecable while the single-tool
 *                     invariant holds (its cost is table lookups). The C-granularity checklist
 *                     gate follows ┬з4.2.9 retirement (persistent 100% pass with untouched
 *                     criteria тЖ?advisory тЖ?retired). `autonomousGateCommands` is a CARRIER,
 *                     never the only gate (DEFAULT_AUTONOMOUS_GATES.commands is configurable тА? *                     J1 fails there; the non-configurable gates live here).
 *
 * UNINSTALLABILITY: `k3WrapGate` is designed to be called INLINE at the `wrapToolDefinition`
 * call sites (e.g. `ipython.ts:707` тЖ?`k3WrapGate(wrapToolDefinition(...), тА?`). No settings
 * flag, no env switch, no registry toggle: removal = editing source = surviving `make verify`
 * and the W4 invariants suite.
 *
 * GAP-061 FACT-CORRECTION INTAKE (this module is the namedцЙ┐цОечВ?:
 * `packages/coding-agent/src/core/prompt-admission.ts` EXISTS (contra GAP-012's "no such file")
 * on all three historical pins тА?but exports ONLY cancellation semantics
 * (`PromptAdmissionCancelledError` / `throwIfPromptAdmissionCancelled` / `waitForPromptAdmission`:
 * await a promise until an AbortSignal fires). It contains NO admission-approval logic, so it
 * CANNOT carry the gate itself. Disposition recorded here and in evidence/impl_t3_after.md:
 *   - as a TEST ANCHOR: usable тА?the file is stable across pins and its exports give the gate a
 *     ready-made, well-tested cancellation envelope; the k3-stage-gate test pins this usage.
 *   - as an INSERTION POINT: `waitForPromptAdmission` is adopted below as the CANCELLATION
 *     ENVELOPE of the admission check (gate evaluation is abortable exactly like upstream
 *     prompt admission), NOT as the admission logic. Admission logic is K3's own (stage-gate.ts).
 */

import { throwIfPromptAdmissionCancelled, waitForPromptAdmission } from "../../core/prompt-admission.js";
import type { GateVerdict, L1Context, L1Predicate, PredicateResult } from "./predicates.js";
import type { L1Evaluation, StageGate } from "./stage-gate.js";

export { PromptAdmissionCancelledError } from "../../core/prompt-admission.js";

// ---------------------------------------------------------------------------
// B granularity тА?per-tool-call hard gate (wrapToolDefinition boundary, щФ?A3/A4)
// ---------------------------------------------------------------------------

/** The minimal AgentTool surface the wrapper needs (kept structural to avoid upstream churn). */
export interface WrappedTool<TParams = unknown, TResult = unknown> {
	readonly name: string;
	execute(
		toolCallId: string,
		params: TParams,
		signal?: AbortSignal,
		onUpdate?: unknown,
		...rest: unknown[]
	): Promise<TResult>;
	[key: string]: unknown;
}

export class K3GateBlockedError extends Error {
	constructor(
		readonly gateId: string,
		readonly evaluation: L1Evaluation,
	) {
		super(
			`K3 gate ${gateId} blocked tool call: ${evaluation.verdict} ` +
				`[${evaluation.reason_codes.join(", ")}] тА?advancement is ledger-audited, not self-reported`,
		);
		this.name = "K3GateBlockedError";
	}
}

export interface K3WrapGateOptions {
	readonly gate: StageGate;
	/** Supplies the CURRENT phase context at call time (phase switches invalidate the cache). */
	readonly contextProvider: () => L1Context;
	/**
	 * Mechanical predicates to run at the tool-call boundary. MUST stay family-1/2 mechanical
	 * (┬з4.2.8): admission, quota, pre-action boundary checks. Anything needing semantics sinks
	 * to the C granularity.
	 */
	readonly predicates: readonly L1Predicate[];
	readonly gateId?: string;
}

/**
 * Inline per-call hard gate around an already-wrapped tool. Overhead is table lookups; ledger
 * SQL results are cached per phase inside StageGate. Only mechanical L1 predicates run here тА? * the k3-stage-gate test statically asserts no provider/LLM module is reachable (GAP-055 тС?.
 */
export function k3WrapGate<T extends WrappedTool>(tool: T, options: K3WrapGateOptions): T {
	const gateId = options.gateId ?? "tool_call.admission";
	return {
		...tool,
		execute: async (
			toolCallId: string,
			params: unknown,
			signal?: AbortSignal,
			onUpdate?: unknown,
			...rest: unknown[]
		) => {
			// GAP-061 disposition: upstream cancellation envelope reused verbatim тА?the admission
			// check is abortable exactly like upstream prompt admission, and nothing more.
			throwIfPromptAdmissionCancelled(signal);
			const ctx = options.contextProvider();
			const evaluation = await waitForPromptAdmission(
				Promise.resolve().then(() => options.gate.checkToolCall(ctx, options.predicates)),
				signal,
			);
			if (evaluation.verdict !== "PASS") {
				// Denied tool calls are ledgered gate decisions, never silent exceptions (Axiom 5).
				options.gate.recordToolCallBlock(gateId, ctx.phase, evaluation);
				throw new K3GateBlockedError(gateId, evaluation);
			}
			return tool.execute(toolCallId, params, signal, onUpdate, ...rest);
		},
	} as T;
}

// ---------------------------------------------------------------------------
// C granularity тА?phase-completion gate (goal.complete hostHandler, щФ?A2/A8)
// ---------------------------------------------------------------------------

/** One structured checklist item: a requirement plus the ledger pointers that prove it. */
export interface ChecklistItem {
	readonly requirement: string;
	readonly done: boolean;
	/** Ledger event ids / evidence ids proving completion (burden of proof on the applicant). */
	readonly evidence_pointers: readonly string[];
}

export interface GoalCompleteGateResult {
	readonly allowed: boolean;
	readonly verdict: "PASS" | "RECYCLE";
	readonly missing: readonly string[];
}

/**
 * The upstream completion-audit clause exists only as prompt text (goals.ts: "Before marking
 * the goal complete, audit the current state against every requirementтА?). This sinks it into
 * code: `goal.complete` is admitted only when every checklist item is done AND carries at least
 * one evidence pointer. Mechanical only тА?pointer RESOLUTION and semantic spot checks belong to
 * the full `StageGate.decide("goal.complete", тА?` path; this pre-gate is what the hostHandler
 * calls synchronously before honouring the request.
 */
export function checkGoalCompletion(checklist: readonly ChecklistItem[]): GoalCompleteGateResult {
	const missing: string[] = [];
	if (checklist.length === 0) missing.push("empty checklist: completion without declared requirements is self-report");
	for (const item of checklist) {
		if (!item.done) missing.push(`not done: ${item.requirement}`);
		else if (item.evidence_pointers.length === 0) missing.push(`no evidence pointer: ${item.requirement}`);
	}
	return { allowed: missing.length === 0, verdict: missing.length === 0 ? "PASS" : "RECYCLE", missing };
}

export interface GoalCompleteGateOptions {
	readonly gate: StageGate;
	readonly contextProvider: () => L1Context;
	/** Supplies the structured checklist for the active goal (from the phase-admission contract). */
	readonly checklistProvider: () => readonly ChecklistItem[];
}

/**
 * Wraps a `goal.complete` host handler: checklist gate first (RECYCLE тЖ?the goal STAYS OPEN and
 * the handler returns a structured refusal instead of completing), then the full ledger-audited
 * phase.exit decision. Designed to be inserted in `_createKernelHostHandlers` around the
 * `goal.complete` branch (agent-session.ts:8678).
 */
export function createGoalCompleteGate<TPayload, TResult>(
	options: GoalCompleteGateOptions,
	inner: (payload: TPayload) => Promise<TResult>,
): (payload: TPayload) => Promise<TResult | { refused: true; verdict: GateVerdict; missing: readonly string[] }> {
	return async (payload: TPayload) => {
		const checklist = options.checklistProvider();
		const pre = checkGoalCompletion(checklist);
		// The checklist is fed into the full gate as one more MECHANICAL predicate (count of done
		// flags and pointer lengths), so the refusal and its reason land as ONE gate.decision row тА?		// the ledgered verdict always matches what the handler actually did.
		const checklistPredicate: L1Predicate = (): PredicateResult => ({
			id: "C1",
			check: "goal completion checklist: every requirement done and evidence-pointered",
			ok: pre.allowed,
			verdict_on_fail: "RECYCLE",
