export type DomainCapability = "read" | "append" | "mutate" | "spawn" | "network";

export interface DomainSpec {
	readonly domain: DomainName;
	readonly capabilities: readonly DomainCapability[];
	/** Path prefixes this handler may touch; checked against the filesystem allowlist. */
	readonly pathPrefixes?: readonly string[];
	/** Hosts this handler may reach; requires the `network` capability. */
	readonly hosts?: readonly string[];
	/**
	 * Mirrors the `agent-observe` SKILL.md wording "read-only and exposes no mutation commands" 鈥?	 * but here it is ENFORCED: a read-only spec that declares `mutate` is rejected at registration.
	 */
	readonly readOnly?: boolean;
}

/** Marker property proving a handler passed through the proxy. */
export const GUARD_MARK = "__k3_guarded" as const;

export type GuardedHandler = HostRequestHandler & {
	readonly [GUARD_MARK]: true;
	readonly __k3_domain: DomainName;

